#include <iostream>
#include <string>
#include <sstream>
#include <numeric>

int main() {
    std::ios_base::sync_with_stdio(false);
    std::cin.tie(nullptr);

    long long n;
    std::cin >> n;
    n += 1;
    std::cin.ignore(); 

    std::string line;
    std::getline(std::cin, line);
    std::stringstream ss(line);

    long long total = 0;
    long long val;
    while (ss >> val) {
        total += val;
    }

    int count = 0;
    for (int i = 1; i <= 5; ++i) {
        if ((i + total) % n != 1) {
            count++;
        }
    }

    std::cout << count << std::endl;
    return 0;
}

